// Select social posts: re-validate every Approved row; writes nothing.
const DRY_RUN = true; // while true nothing is published and nothing is set to Sent
const CAP = 3;
const GRACE_MS = 5 * 60 * 1000;
const txt = v => !v ? "" : v.title ? v.title.map(t => t.plain_text).join("") : v.rich_text ? v.rich_text.map(t => t.plain_text).join("") : v.select ? (v.select.name || "") : "";
const prop = (pr, name) => { for (const k in pr) if (k.toLowerCase() === name) return pr[k]; return null; };
const parse = draft => {
  const ch = (draft.match(/^Channel:\s*(\w+)/im) || [])[1] || "";
  const headline = (draft.match(/^Headline:\s*(.+)$/im) || [])[1] || "";
  const body = (draft.match(/^Body:\n([\s\S]*?)(?:\n\n(?:Image|Hashtags|Suggested timing|NEEDS HUMAN):|$)/im) || [])[1] || "";
  const image = (draft.match(/^Image:\s*(https:\/\/\S+)/im) || [])[1] || "";
  const tags = (draft.match(/^Hashtags:\s*(.+)$/im) || [])[1] || "";
  const needsHuman = /^NEEDS HUMAN:/im.test(draft);
  return { channel: ch.toLowerCase(), headline: headline.trim(), body: body.trim(), image, tags: tags.trim(), needsHuman };
};
const skipped = [], picked = [];
for (const it of $input.all()) {
  const p = it.json;
  if (!p || !p.id) continue;
  const pr = p.properties || {};
  let title = "";
  for (const k in pr) if (pr[k] && pr[k].type === "title") title = txt(pr[k]);
  const v = { id: p.id, title: title || "(untitled)", status: txt(prop(pr, "status")), type: txt(prop(pr, "type")),
    qa: txt(prop(pr, "qa result")), by: txt(prop(pr, "decided by")), draft: txt(prop(pr, "draft")).trim(),
    decided_at: ((prop(pr, "decided at") || {}).date || {}).start || "", edited: p.last_edited_time || "" };
  const why = (() => {
    if (v.status !== "Approved") return "status is not Approved";
    if (v.type !== "Content") return "type is not Content";
    if (!v.draft) return "Draft is empty";
    if (v.qa === "Fail" && !v.by) return "QA Fail without Decided By";
    if (!v.decided_at) return "Decided At missing";
    const da = /T/.test(v.decided_at) ? Date.parse(v.decided_at) : Date.parse(v.decided_at) + 86400000;
    if (Date.parse(v.edited) > da + GRACE_MS) return "edited after approval; set back to Awaiting Approval and re-approve";
    return "";
  })();
  const m = parse(v.draft);
  if (!["facebook", "instagram"].includes(m.channel)) continue; // not a social post; Send handles other Content
  if (why) { skipped.push({ id: v.id, title: v.title, reason: why }); continue; }
  if (m.needsHuman) { skipped.push({ id: v.id, title: v.title, reason: "draft is flagged NEEDS HUMAN" }); continue; }
  if (!m.body) { skipped.push({ id: v.id, title: v.title, reason: "no Body found in Draft" }); continue; }
  if (m.channel === "instagram" && !m.image) { skipped.push({ id: v.id, title: v.title, reason: "Instagram needs an Image: https URL line" }); continue; }
  const message = [m.headline, m.body, m.tags].filter(Boolean).join("\n\n").slice(0, m.channel === "instagram" ? 2200 : 5000);
  picked.push({ id: v.id, title: v.title, channel: m.channel, message, image_url: m.image, decided_at: v.decided_at });
}
picked.sort((a, b) => String(a.decided_at).localeCompare(String(b.decided_at)));
const run = picked.slice(0, CAP);
const log = { kind: "summary", task: "Social publisher run" + (DRY_RUN ? " (dry run)" : ""), status: "Done",
  notes: ((DRY_RUN ? "DRY RUN: would publish " : "Publishing ") + run.length + " post(s): " + run.map(r => r.channel + " - " + r.title).join("; ") +
    (skipped.length ? ". Skipped: " + skipped.map(s => s.title + " (" + s.reason + ")").join("; ") : "")).slice(0, 1900) };
return [{ json: log }, ...run.map(r => ({ json: { kind: "post", action: DRY_RUN ? "would_publish" : "publish", ...r } }))];

// Build Graph API requests. The Page token lives only in the n8n credential, never here.
const PAGE = "REPLACE_WITH_FACEBOOK_PAGE_ID", IG = "REPLACE_WITH_INSTAGRAM_ACCOUNT_ID", V = "v21.0";
return $input.all().map(it => {
  const j = it.json;
  if (j.channel === "facebook") {
    const withImg = !!j.image_url;
    return { json: { ...j, fb_url: "https://graph.facebook.com/" + V + "/" + PAGE + (withImg ? "/photos" : "/feed"),
      fb_body: withImg ? { url: j.image_url, caption: j.message, published: true } : { message: j.message } } };
  }
  return { json: { ...j, ig_create_url: "https://graph.facebook.com/" + V + "/" + IG + "/media",
    ig_publish_url: "https://graph.facebook.com/" + V + "/" + IG + "/media_publish",
    ig_create_body: { image_url: j.image_url, caption: j.message } } };
});

// Published only if Graph returned a NEW id. A disabled/failed publisher passes the incoming item through, which still carries kind/channel.
return $input.all().map(it => {
  const src = $('Build Graph requests').item.json;
  let created = "";
  if (src.channel === "instagram") { try { created = String($('Create Instagram media').item.json.id || ""); } catch (e) { created = ""; } }
  const j = it.json || {};
  const ok = !!j.id && !j.error && j.kind === undefined && j.id !== src.id && (src.channel !== "instagram" || String(j.id) !== created);
  return { json: { id: src.id, title: src.title, channel: src.channel, confirmed: ok, graph_id: ok ? String(j.id) : "" } };
});
